import{_ as t,c as h,o as i,a2 as g}from"./chunks/framework.B7el9cAC.js";const m=JSON.parse('{"title":"Mục 6.1 – Văn Hóa Mạng","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-6/6.1-van-hoa-mang.md","filePath":"chuong-6/6.1-van-hoa-mang.md","lastUpdated":1775365196000}'),o={name:"chuong-6/6.1-van-hoa-mang.md"};function a(r,n,c,u,l,d){return i(),h("div",null,[...n[0]||(n[0]=[g('<h1 id="muc-6-1-–-van-hoa-mang" tabindex="-1">Mục 6.1 – Văn Hóa Mạng <a class="header-anchor" href="#muc-6-1-–-van-hoa-mang" aria-label="Permalink to &quot;Mục 6.1 – Văn Hóa Mạng&quot;">​</a></h1><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><p><strong>Tại sao cần học về văn hóa mạng?</strong></p><p>Hãy tưởng tượng bạn đang ở ngoài đường. Bạn sẽ không la hét, không xúc phạm người khác, không ném đồ vào người lạ – vì xã hội có quy tắc ứng xử. <strong>Trên internet cũng vậy.</strong></p><p>Nhưng nhiều người nghĩ: &quot;Mình giấu tên trên mạng, chẳng ai biết mình là ai&quot; → rồi nói những điều rất thô lỗ, thậm chí gây hại cho người khác.</p><p>Thực tế: Những gì bạn làm trên mạng <strong>để lại dấu vết số</strong> và <strong>có thể truy ra được</strong>. Quan trọng hơn, ngôn ngữ và hành động online ảnh hưởng thật sự đến cảm xúc con người thật.</p><p><strong>Văn hóa mạng (Netiquette)</strong> = tập hợp các chuẩn mực hành vi được chấp nhận khi giao tiếp trên internet.</p><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="van-hoa-mang-la-gi" tabindex="-1">Văn hóa mạng là gì? <a class="header-anchor" href="#van-hoa-mang-la-gi" aria-label="Permalink to &quot;Văn hóa mạng là gì?&quot;">​</a></h3><p><strong>Văn hóa mạng</strong> (hay còn gọi là <em>Netiquette</em> – ghép từ &quot;Network&quot; + &quot;Etiquette&quot;) là hệ thống các quy tắc ứng xử, thái độ và hành vi đúng đắn khi sử dụng internet, bao gồm:</p><ul><li>Mạng xã hội (Facebook, TikTok, Instagram)</li><li>Nhóm chat (Zalo, Messenger, Telegram)</li><li>Email</li><li>Diễn đàn, bình luận trực tuyến</li><li>Game online</li></ul><h3 id="cyberbullying-bat-nat-truc-tuyen-la-gi" tabindex="-1">Cyberbullying (Bắt nạt trực tuyến) là gì? <a class="header-anchor" href="#cyberbullying-bat-nat-truc-tuyen-la-gi" aria-label="Permalink to &quot;Cyberbullying (Bắt nạt trực tuyến) là gì?&quot;">​</a></h3><p><strong>Cyberbullying</strong> = hành vi <strong>cố ý</strong>, <strong>lặp đi lặp lại</strong> gây hại, làm xấu hổ, đe dọa hoặc tấn công tâm lý một người khác thông qua các thiết bị kỹ thuật số.</p><p><strong>Các hình thức Cyberbullying:</strong></p><ul><li><strong>Harassment (Quấy rối):</strong> Gửi tin nhắn xúc phạm, đe dọa liên tục</li><li><strong>Flaming (Chửi bới):</strong> Đăng bình luận thô lỗ, kích động, cãi vã trực tuyến</li><li><strong>Outing (Phơi bày):</strong> Chia sẻ thông tin riêng tư của người khác mà không được phép</li><li><strong>Exclusion (Loại trừ):</strong> Cố ý không cho ai vào nhóm chat, nhóm game, tạo cảm giác bị cô lập</li><li><strong>Impersonation (Giả mạo):</strong> Lập tài khoản giả mạo người khác để làm xấu họ</li><li><strong>Trolling (Câu chuyện khiêu khích):</strong> Đăng nội dung gây tranh cãi chỉ để xem người khác tức giận</li></ul><h3 id="quy-tac-ung-xu-tren-mang-10-quy-tac-vang" tabindex="-1">Quy tắc ứng xử trên mạng (10 quy tắc vàng): <a class="header-anchor" href="#quy-tac-ung-xu-tren-mang-10-quy-tac-vang" aria-label="Permalink to &quot;Quy tắc ứng xử trên mạng (10 quy tắc vàng):&quot;">​</a></h3><ol><li>Nhớ rằng phía màn hình kia cũng là <strong>con người thật</strong></li><li>Tuân theo chuẩn mực xã hội <strong>ngoài đời thực</strong> khi online</li><li><strong>Suy nghĩ trước khi đăng</strong> – những gì lên mạng rất khó xóa hoàn toàn</li><li>Tôn trọng <strong>thời gian và băng thông</strong> của người khác</li><li>Chia sẻ <strong>kiến thức</strong> và giúp đỡ cộng đồng</li><li>Kiềm chế khi <strong>tranh luận</strong> – không để xúc cảm kiểm soát ngôn từ</li><li>Tôn trọng <strong>quyền riêng tư</strong> của người khác</li><li>Không lạm dụng <strong>quyền lực</strong> (admin nhóm, quản lý diễn đàn)</li><li>Tha thứ cho <strong>lỗi lầm</strong> của người mới dùng internet</li><li><strong>Báo cáo</strong> nội dung vi phạm thay vì tham gia hoặc im lặng</li></ol><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><p><strong>Thực chất văn hóa mạng là gì?</strong></p><p>Nó là <strong>đạo đức áp dụng vào không gian số</strong>. Không phải quy tắc kỹ thuật, mà là <strong>thái độ con người</strong>.</p><p><strong>So sánh hành vi ngoài đời và trên mạng:</strong></p><table tabindex="0"><thead><tr><th>Ngoài đời</th><th>Trên mạng (tương đương)</th></tr></thead><tbody><tr><td>La hét vào mặt người</td><td>Viết TOÀN CHỮ HOA trong tin nhắn</td></tr><tr><td>Xúc phạm công khai trước đám đông</td><td>Đăng bình luận chê bai trước hàng nghìn người</td></tr><tr><td>Kể chuyện riêng tư của bạn bè</td><td>Screenshot và chia sẻ tin nhắn riêng</td></tr><tr><td>Giả vờ là người khác để lừa</td><td>Lập tài khoản fake giả mạo</td></tr><tr><td>Không mời ai vào nhóm bạn</td><td>Kick người khỏi group chat, không cho vào</td></tr></tbody></table><p><strong>Ẩn danh không có nghĩa là vô trách nhiệm.</strong> IP, lịch sử truy cập, metadata – tất cả đều có thể được truy lại bởi cơ quan chức năng khi cần thiết.</p><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><p>Quy trình xử lý khi gặp nội dung xấu hoặc Cyberbullying:</p><ol><li><strong>Nhận diện</strong> → Xác định đây có phải hành vi bắt nạt/vi phạm không</li><li><strong>Không phản ứng ngay</strong> → Đừng đáp trả bằng cảm xúc, tránh leo thang</li><li><strong>Chụp màn hình lưu bằng chứng</strong> → Lưu screenshot trước khi nội dung bị xóa</li><li><strong>Chặn (Block) người vi phạm</strong> → Ngăn họ tiếp tục tiếp cận bạn</li><li><strong>Báo cáo (Report)</strong> → Dùng tính năng report của nền tảng (Facebook, TikTok...)</li><li><strong>Nói với người lớn tin tưởng</strong> → Cha mẹ, giáo viên, thầy cô chủ nhiệm</li><li><strong>Liên hệ cơ quan chức năng</strong> → Nếu nghiêm trọng, có thể báo Công an hoặc đường dây hỗ trợ</li></ol><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-co-ban-ung-xu-trong-nhom-chat-lop-hoc" tabindex="-1">Ví dụ 1 – Cơ bản: Ứng xử trong nhóm chat lớp học <a class="header-anchor" href="#vi-du-1-–-co-ban-ung-xu-trong-nhom-chat-lop-hoc" aria-label="Permalink to &quot;Ví dụ 1 – Cơ bản: Ứng xử trong nhóm chat lớp học&quot;">​</a></h3><p><strong>Tình huống:</strong> Nhóm Zalo lớp 10A1 đang thảo luận bài tập. Bạn Minh gõ nhầm đáp án sai.</p><p><strong>Cách ứng xử SAI:</strong></p><blockquote><p>&quot;Ôi trời ơi bạn Minh ngu v ạ 😂😂 sai hết rồi&quot; &quot;Ai lại làm vậy bao giờ, học đến lớp 10 rồi mà&quot;</p></blockquote><p><strong>Cách ứng xử ĐÚNG:</strong></p><blockquote><p>&quot;Bạn Minh ơi, mình nghĩ kết quả đó chưa đúng nha. Theo mình thì nên làm thế này: [giải thích]. Bạn thử lại xem sao!&quot;</p></blockquote><p><strong>Tại sao quan trọng:</strong> Bạn Minh là người thật, có cảm xúc thật. Bình luận xấu trong nhóm lớp ảnh hưởng đến tự tin của bạn ấy.</p><hr><h3 id="vi-du-2-–-thuc-te-cyberbullying-tren-mang-xa-hoi" tabindex="-1">Ví dụ 2 – Thực tế: Cyberbullying trên mạng xã hội <a class="header-anchor" href="#vi-du-2-–-thuc-te-cyberbullying-tren-mang-xa-hoi" aria-label="Permalink to &quot;Ví dụ 2 – Thực tế: Cyberbullying trên mạng xã hội&quot;">​</a></h3><p><strong>Tình huống:</strong> Bạn Lan đăng ảnh lên Facebook. Một nhóm bạn cùng lớp vào bình luận chê bai ngoại hình, tag nhiều người khác vào, tạo cả sticker từ ảnh của Lan.</p><p><strong>Hậu quả thực tế:</strong></p><ul><li>Lan cảm thấy xấu hổ, lo âu, không muốn đến trường</li><li>Lan xóa tài khoản, cô lập bản thân</li><li>Đây là hành vi <strong>Cyberbullying nghiêm trọng</strong> – có thể bị kỷ luật trường, thậm chí xử lý hành chính</li></ul><p><strong>Cách phòng ngừa:</strong> Trước khi bình luận, tự hỏi: <em>&quot;Nếu nói câu này ngoài đời, mình có nói không?&quot;</em></p><hr><h3 id="vi-du-3-–-nang-cao-phan-tich-tinh-huong-phuc-tap" tabindex="-1">Ví dụ 3 – Nâng cao: Phân tích tình huống phức tạp <a class="header-anchor" href="#vi-du-3-–-nang-cao-phan-tich-tinh-huong-phuc-tap" aria-label="Permalink to &quot;Ví dụ 3 – Nâng cao: Phân tích tình huống phức tạp&quot;">​</a></h3><p><strong>Tình huống:</strong> Bạn thấy một bài đăng trên mạng tố cáo thầy giáo có hành vi không tốt. Bạn không biết thật hay giả. Nhiều người đang share ào ào.</p><p><strong>Phân tích:</strong></p><ul><li>Nếu thông tin <strong>sai</strong> → chia sẻ = tham gia lan truyền tin giả, có thể gây hại oan cho thầy</li><li>Nếu thông tin <strong>đúng</strong> → vẫn nên báo cáo qua kênh chính thức, không phải phán xét công khai trên mạng</li></ul><p><strong>Cách ứng xử đúng:</strong></p><ol><li>Không chia sẻ khi chưa xác minh</li><li>Nếu nghiêm trọng, báo cáo lên ban giám hiệu hoặc cơ quan chức năng</li><li>Tôn trọng quyền được xét xử công bằng của mọi người</li></ol><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="so-sanh-hanh-vi-tot-va-xau-tren-mang" tabindex="-1">So sánh hành vi tốt và xấu trên mạng <a class="header-anchor" href="#so-sanh-hanh-vi-tot-va-xau-tren-mang" aria-label="Permalink to &quot;So sánh hành vi tốt và xấu trên mạng&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hành vi tốt</th><th>Hành vi xấu</th></tr></thead><tbody><tr><td>Dùng ngôn ngữ lịch sự, tôn trọng</td><td>Chửi bới, xúc phạm, dùng từ ngữ thô tục</td></tr><tr><td>Kiểm tra nguồn trước khi chia sẻ</td><td>Share tin chưa kiểm chứng</td></tr><tr><td>Bảo vệ thông tin riêng tư của người khác</td><td>Đăng/chia sẻ ảnh/thông tin của người khác khi chưa hỏi</td></tr><tr><td>Report nội dung vi phạm</td><td>Im lặng hoặc tham gia vào hành vi xấu</td></tr><tr><td>Hỗ trợ người đang bị bắt nạt</td><td>Xem và không làm gì</td></tr></tbody></table><h3 id="so-sanh-cac-hinh-thuc-cyberbullying" tabindex="-1">So sánh các hình thức Cyberbullying <a class="header-anchor" href="#so-sanh-cac-hinh-thuc-cyberbullying" aria-label="Permalink to &quot;So sánh các hình thức Cyberbullying&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hình thức</th><th>Mô tả</th><th>Ví dụ</th></tr></thead><tbody><tr><td>Harassment</td><td>Quấy rối liên tục</td><td>Nhắn tin đe dọa hàng ngày</td></tr><tr><td>Outing</td><td>Tiết lộ thông tin riêng tư</td><td>Đăng ảnh/tin nhắn riêng</td></tr><tr><td>Exclusion</td><td>Loại trừ khỏi nhóm</td><td>Kick khỏi group chat</td></tr><tr><td>Impersonation</td><td>Giả mạo danh tính</td><td>Lập tài khoản fake</td></tr><tr><td>Trolling</td><td>Câu kéo tranh cãi</td><td>Bình luận khiêu khích</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>✅ <strong>Văn hóa mạng (Netiquette)</strong> = quy tắc ứng xử văn minh trên internet</li><li>✅ <strong>Cyberbullying</strong> = bắt nạt trực tuyến – cố ý, lặp lại, qua thiết bị số</li><li>✅ Ẩn danh <strong>không</strong> có nghĩa là không bị truy cứu trách nhiệm</li><li>✅ Viết TOÀN CHỮ HOA = hét vào mặt người khác (không lịch sự)</li><li>✅ Khi bị bắt nạt: <strong>Không phản ứng ngay → Lưu bằng chứng → Block → Report → Nói với người lớn</strong></li><li>✅ Trước khi đăng: hỏi bản thân <em>&quot;Mình có nói điều này ngoài đời không?&quot;</em></li><li>✅ Thông tin chưa kiểm chứng: <strong>không chia sẻ</strong></li><li>✅ Các hình thức Cyberbullying: Harassment, Flaming, Outing, Exclusion, Impersonation, Trolling</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><h3 id="cau-1-de-netiquette-la-ghep-cua-hai-tu-tieng-anh-nao" tabindex="-1">Câu 1 (Dễ): &quot;Netiquette&quot; là ghép của hai từ tiếng Anh nào? <a class="header-anchor" href="#cau-1-de-netiquette-la-ghep-cua-hai-tu-tieng-anh-nao" aria-label="Permalink to &quot;Câu 1 (Dễ): &quot;Netiquette&quot; là ghép của hai từ tiếng Anh nào?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> <strong>Network</strong> + <strong>Etiquette</strong> (Quy tắc ứng xử trên mạng)</p></blockquote><hr><h3 id="cau-2-de-hanh-vi-nao-sau-đay-la-cyberbullying" tabindex="-1">Câu 2 (Dễ): Hành vi nào sau đây là Cyberbullying? <a class="header-anchor" href="#cau-2-de-hanh-vi-nao-sau-đay-la-cyberbullying" aria-label="Permalink to &quot;Câu 2 (Dễ): Hành vi nào sau đây là Cyberbullying?&quot;">​</a></h3><p><strong>A.</strong> Gửi ảnh chúc mừng sinh nhật cho bạn<br><strong>B.</strong> Liên tục nhắn tin đe dọa và chửi bới ai đó<br><strong>C.</strong> Chia sẻ bài học hay lên nhóm lớp<br><strong>D.</strong> Tag bạn bè vào meme vui</p><blockquote><p><strong>Đáp án: B</strong> – Gửi tin nhắn đe dọa, chửi bới liên tục là hành vi Harassment – một dạng Cyberbullying.</p></blockquote><hr><h3 id="cau-3-trung-binh-tai-sao-viec-an-danh-tren-mang-khong-đong-nghia-voi-khong-co-trach-nhiem" tabindex="-1">Câu 3 (Trung bình): Tại sao việc &quot;ẩn danh trên mạng&quot; không đồng nghĩa với &quot;không có trách nhiệm&quot;? <a class="header-anchor" href="#cau-3-trung-binh-tai-sao-viec-an-danh-tren-mang-khong-đong-nghia-voi-khong-co-trach-nhiem" aria-label="Permalink to &quot;Câu 3 (Trung bình): Tại sao việc &quot;ẩn danh trên mạng&quot; không đồng nghĩa với &quot;không có trách nhiệm&quot;?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Mỗi thiết bị kết nối internet đều có địa chỉ IP có thể truy ra. Lịch sử đăng nhập, metadata, thông tin tài khoản đều được lưu trữ trên máy chủ. Cơ quan chức năng có thể yêu cầu các nền tảng (Facebook, Google...) cung cấp thông tin người dùng khi điều tra. Luật pháp Việt Nam (Luật An ninh mạng 2018) quy định rõ trách nhiệm pháp lý với hành vi vi phạm trên mạng.</p></blockquote><hr><h3 id="cau-4-trung-binh-ban-nhan-đuoc-tin-nhan-tu-nguoi-la-đe-doa-va-xuc-pham-ban-lien-tuc-ban-nen-lam-gi-theo-đung-thu-tu" tabindex="-1">Câu 4 (Trung bình): Bạn nhận được tin nhắn từ người lạ đe dọa và xúc phạm bạn liên tục. Bạn nên làm gì theo đúng thứ tự? <a class="header-anchor" href="#cau-4-trung-binh-ban-nhan-đuoc-tin-nhan-tu-nguoi-la-đe-doa-va-xuc-pham-ban-lien-tuc-ban-nen-lam-gi-theo-đung-thu-tu" aria-label="Permalink to &quot;Câu 4 (Trung bình): Bạn nhận được tin nhắn từ người lạ đe dọa và xúc phạm bạn liên tục. Bạn nên làm gì theo đúng thứ tự?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> (1) Không trả lời ngay; (2) Chụp màn hình lưu bằng chứng; (3) Block người đó; (4) Report tài khoản đó lên nền tảng; (5) Nói với cha mẹ hoặc giáo viên; (6) Nếu nghiêm trọng, báo Công an.</p></blockquote><hr><h3 id="cau-5-van-dung-phan-tich-tinh-huong-ban-thay-co-nguoi-đang-anh-che-meme-tu-anh-cua-ban-hoc-ma-khong-hoi-y-kien-ban-cam-thay-xau-ho-đay-la-loai-cyberbullying-nao-ban-xu-ly-the-nao" tabindex="-1">Câu 5 (Vận dụng): Phân tích tình huống: Bạn thấy có người đăng ảnh chế (meme) từ ảnh của bạn học mà không hỏi ý kiến. Bạn cảm thấy xấu hổ. Đây là loại Cyberbullying nào? Bạn xử lý thế nào? <a class="header-anchor" href="#cau-5-van-dung-phan-tich-tinh-huong-ban-thay-co-nguoi-đang-anh-che-meme-tu-anh-cua-ban-hoc-ma-khong-hoi-y-kien-ban-cam-thay-xau-ho-đay-la-loai-cyberbullying-nao-ban-xu-ly-the-nao" aria-label="Permalink to &quot;Câu 5 (Vận dụng): Phân tích tình huống: Bạn thấy có người đăng ảnh chế (meme) từ ảnh của bạn học mà không hỏi ý kiến. Bạn cảm thấy xấu hổ. Đây là loại Cyberbullying nào? Bạn xử lý thế nào?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Đây là <strong>Outing</strong> (phơi bày/sử dụng ảnh riêng tư trái phép). Cách xử lý: (1) Yêu cầu người đó xóa ảnh ngay; (2) Nếu không xóa, Report bài đăng vì vi phạm quyền riêng tư; (3) Nói với giáo viên chủ nhiệm nếu là bạn cùng lớp; (4) Lưu bằng chứng. Đây cũng có thể vi phạm Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân.</p></blockquote><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Quan niệm sai</th><th>Thực tế đúng</th></tr></thead><tbody><tr><td>&quot;Mình ẩn danh, nên làm gì cũng được&quot;</td><td>IP và dữ liệu hoạt động đều có thể truy ra</td></tr><tr><td>&quot;Chỉ là đùa thôi, không ai sao cả&quot;</td><td>Đùa liên tục gây tổn thương = Cyberbullying thật sự</td></tr><tr><td>&quot;Chia sẻ tin tức không cần kiểm chứng – ai cũng làm vậy&quot;</td><td>Lan truyền tin giả có thể bị xử phạt hành chính</td></tr><tr><td>&quot;Report không có tác dụng gì&quot;</td><td>Report nhiều lần → nền tảng xem xét và xử lý</td></tr><tr><td>&quot;Cyberbullying chỉ xảy ra với trẻ em nhỏ&quot;</td><td>Ai cũng có thể là nạn nhân, kể cả người lớn</td></tr><tr><td>&quot;Im lặng trước bắt nạt = an toàn&quot;</td><td>Im lặng có thể bị hiểu là đồng lõa; nên lên tiếng hoặc báo cáo</td></tr><tr><td>&quot;Đăng ảnh người khác lên mạng mà không hỏi là bình thường&quot;</td><td>Đăng ảnh người khác khi chưa được đồng ý là vi phạm quyền riêng tư</td></tr><tr><td>&quot;Mạng xã hội là nơi mọi người đều thật thà&quot;</td><td>Nhiều người tạo hình ảnh lý tưởng, không phản ánh thực tế cuộc sống</td></tr><tr><td>&quot;Số lượng like/follow = giá trị của một người&quot;</td><td>Like và follow không đo lường được phẩm giá hay giá trị thực của con người</td></tr><tr><td>&quot;Block người khi bất đồng là hành vi tiêu cực&quot;</td><td>Block là quyền tự bảo vệ không gian số của mỗi người</td></tr><tr><td>&quot;Viết hoa hết chữ chỉ là cách nhấn mạnh&quot;</td><td>VIẾT HOA TOÀN BỘ bị coi là la hét trong văn hóa internet</td></tr><tr><td>&quot;Comment bình thường trên mạng không cần suy nghĩ nhiều&quot;</td><td>Mỗi bình luận để lại dấu vết và có thể ảnh hưởng đến người nhận</td></tr><tr><td>&quot;Người nổi tiếng phải chấp nhận bị chửi mắng&quot;</td><td>Bất kỳ ai cũng có quyền được tôn trọng bất kể mức độ nổi tiếng</td></tr><tr><td>&quot;Share link không cần đọc nội dung&quot;</td><td>Chia sẻ mà không đọc có thể lan truyền thông tin sai</td></tr><tr><td>&quot;Meme châm biếm người khác là hài hước, không hại gì&quot;</td><td>Meme nhắm vào cá nhân có thể gây tổn thương tâm lý nghiêm trọng</td></tr><tr><td>&quot;Đăng địa chỉ, số điện thoại người khác lên mạng không sao&quot;</td><td>Đây là hành vi doxxing, vi phạm quyền riêng tư và có thể bị xử phạt</td></tr><tr><td>&quot;Troll người khác là một hình thức vui vẻ&quot;</td><td>Trolling gây tổn thương và tạo môi trường mạng độc hại</td></tr><tr><td>&quot;Chỉ cần không dùng tên thật là an toàn&quot;</td><td>Nickname kết hợp với các thông tin khác đủ để nhận dạng bạn</td></tr><tr><td>&quot;Mạng xã hội là không gian tự do tuyệt đối&quot;</td><td>Mạng xã hội có quy tắc cộng đồng và luật pháp vẫn áp dụng</td></tr><tr><td>&quot;Inbox riêng thì muốn nói gì cũng được&quot;</td><td>Tin nhắn riêng vẫn có thể bị chụp màn hình và chia sẻ</td></tr><tr><td>&quot;Người nào nhạy cảm quá thì không nên dùng mạng&quot;</td><td>Trách nhiệm thuộc về người gây hại, không phải nạn nhân</td></tr><tr><td>&quot;Video viral thì phải chia sẻ liền&quot;</td><td>Nên kiểm tra nguồn gốc và nội dung trước khi chia sẻ</td></tr><tr><td>&quot;Quy tắc netiquette chỉ áp dụng cho diễn đàn cũ&quot;</td><td>Netiquette áp dụng cho mọi nền tảng số: email, mạng xã hội, game online</td></tr><tr><td>&quot;Đăng bài mới xóa liền thì không ai biết&quot;</td><td>Nội dung đã đăng có thể đã được chụp màn hình hoặc cache</td></tr><tr><td>&quot;Không ai kiểm tra lại lịch sử post cũ&quot;</td><td>Nhà tuyển dụng, trường học thường kiểm tra mạng xã hội của ứng viên</td></tr><tr><td>&quot;Phát ngôn thù ghét chỉ là ý kiến cá nhân&quot;</td><td>Hate speech gây hại cho xã hội và vi phạm điều khoản các nền tảng</td></tr><tr><td>&quot;Group chat riêng thì thoải mái nói bất kỳ điều gì&quot;</td><td>Nội dung trong group chat vẫn có thể bị rò rỉ và gây hậu quả pháp lý</td></tr><tr><td>&quot;Bình luận tiêu cực giúp người ta tiến bộ&quot;</td><td>Phê bình xây dựng khác với bình luận thù ghét; phê bình cần lời lẽ tôn trọng</td></tr><tr><td>&quot;Follow nhiều người không có hại gì&quot;</td><td>Follow nhiều tài khoản độc hại ảnh hưởng đến tâm trạng và nhận thức</td></tr><tr><td>&quot;Đăng ảnh con nít lên mạng là bình thường&quot;</td><td>Đăng ảnh trẻ em mà không được phép có thể gây nguy hiểm cho trẻ</td></tr><tr><td>&quot;Người ta đăng thông tin cá nhân thì mình dùng thoải mái&quot;</td><td>Sử dụng thông tin người khác mà không được phép vẫn vi phạm quyền riêng tư</td></tr><tr><td>&quot;Repost nội dung không cần ghi nguồn&quot;</td><td>Không ghi nguồn là vi phạm bản quyền và thiếu văn hóa</td></tr><tr><td>&quot;Giả mạo tài khoản người khác chỉ để đùa&quot;</td><td>Giả mạo danh tính là hành vi lừa đảo, vi phạm pháp luật</td></tr><tr><td>&quot;Tham gia flamewar là thể hiện quan điểm&quot;</td><td>Flamewar chỉ tạo xung đột, không giải quyết được vấn đề</td></tr><tr><td>&quot;Người nổi tiếng trên mạng thì thông minh và đáng tin&quot;</td><td>Nổi tiếng không đồng nghĩa với chuyên môn hay độ tin cậy</td></tr><tr><td>&quot;Spam group bạn bè là nhắn tin bình thường&quot;</td><td>Spam gây phiền nhiễu và làm mất sự tôn trọng trong giao tiếp</td></tr><tr><td>&quot;Chụp màn hình hội thoại riêng và chia sẻ không sao&quot;</td><td>Chia sẻ hội thoại riêng mà không được phép là vi phạm quyền riêng tư</td></tr><tr><td>&quot;Người dùng internet ở Việt Nam không bị quản lý&quot;</td><td>Việt Nam có Luật An ninh mạng và Nghị định 72/2013/NĐ-CP quản lý không gian mạng</td></tr><tr><td>&quot;Tham gia petition online không có tác dụng&quot;</td><td>Nhiều petitions online đã dẫn đến thay đổi chính sách thực sự</td></tr><tr><td>&quot;Mua followers/likes giúp nổi tiếng thật sự&quot;</td><td>Followers giả không tạo cộng đồng thật và vi phạm điều khoản nền tảng</td></tr><tr><td>&quot;Đăng ảnh bạn bè mà không tag thì okay&quot;</td><td>Vẫn nên hỏi ý kiến dù không tag; họ có quyền từ chối việc đăng ảnh</td></tr><tr><td>&quot;Mạng xã hội giúp kết bạn tốt hơn thực tế&quot;</td><td>Mạng xã hội hỗ trợ nhưng không thay thế được kết nối xã hội thực</td></tr><tr><td>&quot;Người bị bắt nạt nên tự giải quyết một mình&quot;</td><td>Nên tìm sự hỗ trợ từ người lớn, thầy cô hoặc cơ quan có thẩm quyền</td></tr><tr><td>&quot;Chửi thề online chỉ là cách thể hiện cảm xúc&quot;</td><td>Ngôn ngữ thô tục thường xuyên tạo môi trường tiêu cực và ảnh hưởng đến hình ảnh</td></tr><tr><td>&quot;Đọc tin tức từ nguồn lớn là đủ đáng tin&quot;</td><td>Ngay cả nguồn lớn cũng có thể đăng sai; cần kiểm chứng nhiều nguồn</td></tr><tr><td>&quot;Reaction phẫn nộ trên Facebook không có hậu quả&quot;</td><td>Thuật toán Facebook phân phối nhiều hơn bài dùng reaction phẫn nộ, lan tin giả nhanh hơn</td></tr><tr><td>&quot;Người trẻ hiểu công nghệ nên không cần học văn hóa mạng&quot;</td><td>Kỹ năng kỹ thuật và văn hóa ứng xử online là hai điều hoàn toàn khác nhau</td></tr><tr><td>&quot;Không thể bị phạt vì chỉ share bài trên Facebook&quot;</td><td>Nhiều trường hợp đã bị xử phạt vì share nội dung vi phạm</td></tr><tr><td>&quot;Account bị hack thì phải chịu, không làm gì được&quot;</td><td>Có thể báo cáo cho nền tảng và cơ quan an ninh mạng để xử lý</td></tr><tr><td>&quot;Dùng ngôn ngữ internet (teen code) ở mọi nơi đều okay&quot;</td><td>Teen code không phù hợp trong môi trường học thuật, công việc, giao tiếp chính thức</td></tr><tr><td>&quot;Lượt xem cao = nội dung chất lượng&quot;</td><td>Lượt xem phản ánh sự hấp dẫn, không phải chất lượng hay tính chính xác</td></tr><tr><td>&quot;Chỉ có người trong cuộc mới bị ảnh hưởng bởi cyberbullying&quot;</td><td>Người chứng kiến (bystander) cũng bị ảnh hưởng tâm lý và có trách nhiệm can thiệp</td></tr><tr><td>&quot;Mạng xã hội phản ánh đúng thực tế cuộc sống của mọi người&quot;</td><td>Người dùng thường chỉ đăng những khoảnh khắc tích cực, tạo ra hình ảnh méo mó về thực tế</td></tr><tr><td>&quot;Chỉ người trẻ bị ảnh hưởng bởi áp lực từ mạng xã hội&quot;</td><td>Mọi lứa tuổi đều có thể bị ảnh hưởng tâm lý bởi so sánh và áp lực mạng xã hội</td></tr><tr><td>&quot;Xin lỗi online không có giá trị như xin lỗi trực tiếp&quot;</td><td>Lời xin lỗi chân thành online vẫn có giá trị; điều quan trọng là sự chân thành</td></tr><tr><td>&quot;Nói xấu người vắng mặt trong group chat là chuyện nhỏ&quot;</td><td>Nói xấu sau lưng trong group chat tạo văn hóa độc hại và có thể gây hậu quả nghiêm trọng</td></tr></tbody></table>',81)])])}const s=t(o,[["render",a]]);export{m as __pageData,s as default};
